import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site";

// Crawlers only read robots.txt at the domain root, so the live rules (including this site's private
// paths, /latter-day-stats/{admin,api,me,login,auth}) are in samuelbaird.com's robots.txt, generated by
// sites/samuelbaird.com/scripts/build.mjs from packages/family/projects.json. This file only matters
// on the old host, which redirects.
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [{ userAgent: "*", allow: "/", disallow: ["/admin", "/api", "/me", "/login", "/auth"] }],
    sitemap: `${SITE_URL}/sitemap.xml`,
  };
}
